/**
 * SEO — single source of truth for site-level constants.
 *
 * Everything that ends up in a `<link rel="canonical">`, an `og:*` tag or a
 * JSON-LD `@id` must come from here so canonical URLs can never disagree
 * between metadata, structured data and the sitemap.
 */

export const SITE_NAME = 'QuizVerse';

/** Canonical production origin. No trailing slash. */
export const SITE_URL = (process.env.NEXT_PUBLIC_SITE_URL || 'https://quizverse.org').replace(
  /\/+$/,
  ''
);

/** Static share cards (1200×630, generated by scripts/generate-brand-assets.mjs). */
export const DEFAULT_OG_IMAGE = `${SITE_URL}/og/quizverse-og.png`;
export const DEFAULT_OG_IMAGE_ES = `${SITE_URL}/og/quizverse-og-es.png`;
export const DEFAULT_OG_IMAGE_WIDTH = 1200;
export const DEFAULT_OG_IMAGE_HEIGHT = 630;

/** Square brand mark, used by JSON-LD `Organization.logo`. */
export const BRAND_LOGO = `${SITE_URL}/icons/icon-512.png`;

/**
 * Verification and social handles.
 *
 * The plain (non-`NEXT_PUBLIC_`) names are preferred: Next.js only inlines
 * `NEXT_PUBLIC_*` values into the bundle, so a plain variable is always read at
 * runtime and can be added by editing the container env and restarting instead
 * of rebuilding the image. The `NEXT_PUBLIC_` forms are kept as a fallback.
 */
function envValue(plain: string, publicName: string): string | null {
  return (process.env[plain] || process.env[publicName] || '').trim() || null;
}

/** Optional: only emitted when the handle actually belongs to the project. */
export const TWITTER_HANDLE = envValue('TWITTER_HANDLE', 'NEXT_PUBLIC_TWITTER_HANDLE');

/** Google Search Console — HTML tag / meta tag method. */
export const GOOGLE_SITE_VERIFICATION = envValue(
  'GOOGLE_SITE_VERIFICATION',
  'NEXT_PUBLIC_GOOGLE_SITE_VERIFICATION'
);

/** Other console verifications, all optional. */
export const OTHER_VERIFICATIONS = {
  ...(envValue('BING_SITE_VERIFICATION', 'NEXT_PUBLIC_BING_SITE_VERIFICATION')
    ? {
        'msvalidate.01': envValue('BING_SITE_VERIFICATION', 'NEXT_PUBLIC_BING_SITE_VERIFICATION')!,
      }
    : {}),
  ...(envValue('YANDEX_SITE_VERIFICATION', 'NEXT_PUBLIC_YANDEX_SITE_VERIFICATION')
    ? {
        'yandex-verification': envValue(
          'YANDEX_SITE_VERIFICATION',
          'NEXT_PUBLIC_YANDEX_SITE_VERIFICATION'
        )!,
      }
    : {}),
};

/** Home dynamic OG image route (app/[locale]/opengraph-image.tsx). */
export function homeOgImage(locale: string): string {
  return `${SITE_URL}/${locale}/opengraph-image`;
}

/** Per-quiz dynamic OG image route (app/[locale]/quiz/[slug]/opengraph-image.tsx). */
export function quizOgImage(locale: string, slug: string): string {
  return `${SITE_URL}/${locale}/quiz/${encodeURIComponent(slug)}/opengraph-image`;
}

/** Per-category dynamic OG image route (app/[locale]/category/[slug]/opengraph-image.tsx). */
export function categoryOgImage(locale: string, slug: string): string {
  return `${SITE_URL}/${locale}/category/${encodeURIComponent(slug)}/opengraph-image`;
}

/** About page dynamic OG image route (app/[locale]/about/opengraph-image.tsx). */
export function aboutOgImage(locale: string): string {
  return `${SITE_URL}/${locale}/about/opengraph-image`;
}

/** Contact page dynamic OG image route (app/[locale]/contact/opengraph-image.tsx). */
export function contactOgImage(locale: string): string {
  return `${SITE_URL}/${locale}/contact/opengraph-image`;
}

/** Leaderboard page dynamic OG image route (app/[locale]/leaderboard/opengraph-image.tsx). */
export function leaderboardOgImage(locale: string): string {
  return `${SITE_URL}/${locale}/leaderboard/opengraph-image`;
}

/**
 * Per-result dynamic OG card (app/api/og/result/[locale]/[slug]).
 *
 * `shareToken` renders the player's outcome; `challengeToken` adds the
 * challenger's mark so the card becomes a versus (retador vs retado).
 */
export function resultOgImage(
  locale: string,
  slug: string,
  shareToken?: string | null,
  challengeToken?: string | null
): string {
  const base = `${SITE_URL}/api/og/result/${locale}/${encodeURIComponent(slug)}`;
  const params = new URLSearchParams();
  if (shareToken) params.set('s', shareToken);
  if (challengeToken) params.set('c', challengeToken);
  const query = params.toString();
  return query ? `${base}?${query}` : base;
}

/** Absolute URL for a locale-prefixed path. `path` must start with `/`. */
export function absoluteUrl(path: string): string {
  if (/^https?:\/\//.test(path)) return path;
  const normalized = path.startsWith('/') ? path : `/${path}`;
  return `${SITE_URL}${normalized === '/' ? '' : normalized}`;
}

/**
 * Percent-encodes the path segments of a slug while keeping `/` intact.
 * Slugs are ASCII today, but a stray accent or space must never produce an
 * invalid canonical.
 */
export function safePath(...segments: string[]): string {
  return segments
    .map((segment) => segment.replace(/^\/+|\/+$/g, ''))
    .filter(Boolean)
    .map((segment) => encodeURIComponent(segment))
    .join('/');
}
